create table dm_private.community_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,exam text not null check(exam in('uceed','nid','nift','ceed')),topic text not null,title text not null check(char_length(title) between 8 and 160),body text not null check(char_length(body) between 20 and 5000),status text not null default 'visible' check(status in('visible','hidden','locked')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table dm_private.community_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references dm_private.community_posts(id) on delete cascade,parent_id uuid references dm_private.community_comments(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(body) between 2 and 3000),helpful_count integer not null default 0 check(helpful_count>=0),status text not null default 'visible' check(status in('visible','hidden')),created_at timestamptz not null default now());
create table dm_private.community_helpful(user_id uuid not null references auth.users(id) on delete cascade,comment_id uuid not null references dm_private.community_comments(id) on delete cascade,primary key(user_id,comment_id));
create table dm_private.community_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id) on delete cascade,post_id uuid references dm_private.community_posts(id) on delete cascade,comment_id uuid references dm_private.community_comments(id) on delete cascade,reason text not null check(reason in('spam','abuse','copyright','answer_leak','other')),details text check(details is null or char_length(details)<=1000),created_at timestamptz not null default now(),check((post_id is null)<>(comment_id is null)),unique(reporter_id,post_id),unique(reporter_id,comment_id));
create table dm_private.community_moderation_log(id bigint generated always as identity primary key,actor_id uuid not null references auth.users(id),target_type text not null check(target_type in('post','comment')),target_id uuid not null,action text not null check(action in('hide','restore','lock','unlock')),note text,created_at timestamptz not null default now());
alter table dm_private.community_posts enable row level security;alter table dm_private.community_comments enable row level security;alter table dm_private.community_helpful enable row level security;alter table dm_private.community_reports enable row level security;alter table dm_private.community_moderation_log enable row level security;
revoke all on dm_private.community_posts,dm_private.community_comments,dm_private.community_helpful,dm_private.community_reports,dm_private.community_moderation_log from anon,authenticated;
create index community_feed_idx on dm_private.community_posts(created_at desc) where status='visible';create index community_comments_post_idx on dm_private.community_comments(post_id,created_at);
create or replace function public.community_feed(p_exam text default null,p_topic text default null) returns jsonb language sql stable security definer set search_path=pg_catalog,dm_private,public as $$ select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'exam',p.exam,'topic',p.topic,'title',p.title,'body',p.body,'status',p.status,'author',coalesce(nullif(split_part(pr.display_name,' ',1),''),'Student'),'createdAt',p.created_at,'comments',(select count(*) from dm_private.community_comments c where c.post_id=p.id and c.status='visible')) order by p.created_at desc),'[]') from dm_private.community_posts p left join public.profiles pr on pr.user_id=p.author_id where auth.uid() is not null and p.status<>'hidden' and (p_exam is null or p.exam=p_exam) and (p_topic is null or p.topic=p_topic) $$;
create or replace function public.create_community_post(p_exam text,p_topic text,p_title text,p_body text) returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$ declare v uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; insert into dm_private.community_posts(author_id,exam,topic,title,body) values(auth.uid(),p_exam,trim(p_topic),trim(p_title),trim(p_body)) returning id into v; return v; end $$;
create or replace function public.community_thread(p_post_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,dm_private,public as $$ declare v jsonb; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select jsonb_build_object('id',p.id,'title',p.title,'body',p.body,'exam',p.exam,'topic',p.topic,'status',p.status,'comments',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'parentId',c.parent_id,'body',c.body,'helpful',c.helpful_count,'author',coalesce(nullif(split_part(pr.display_name,' ',1),''),'Student')) order by c.created_at) from dm_private.community_comments c left join public.profiles pr on pr.user_id=c.author_id where c.post_id=p.id and c.status='visible'),'[]')) into v from dm_private.community_posts p where p.id=p_post_id and p.status<>'hidden'; if v is null then raise exception 'Post not found'; end if; return v; end $$;
create or replace function public.add_community_comment(p_post_id uuid,p_parent_id uuid,p_body text) returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$ declare v uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if;if not exists(select 1 from dm_private.community_posts where id=p_post_id and status='visible') then raise exception 'Post is unavailable or locked';end if;if p_parent_id is not null and not exists(select 1 from dm_private.community_comments where id=p_parent_id and post_id=p_post_id) then raise exception 'Reply target not found';end if;insert into dm_private.community_comments(post_id,parent_id,author_id,body) values(p_post_id,p_parent_id,auth.uid(),trim(p_body)) returning id into v;return v;end $$;
create or replace function public.mark_community_helpful(p_comment_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,dm_private as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;insert into dm_private.community_helpful values(auth.uid(),p_comment_id) on conflict do nothing;if found then update dm_private.community_comments set helpful_count=helpful_count+1 where id=p_comment_id;end if;end $$;
create or replace function public.report_community_content(p_post_id uuid,p_comment_id uuid,p_reason text,p_details text default null) returns void language plpgsql security definer set search_path=pg_catalog,dm_private as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;insert into dm_private.community_reports(reporter_id,post_id,comment_id,reason,details) values(auth.uid(),p_post_id,p_comment_id,p_reason,nullif(trim(p_details),''));end $$;
create or replace function public.admin_moderate_community(p_target_type text,p_target_id uuid,p_action text,p_note text default null) returns void language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$ begin if not public.is_dmocks_admin() then raise exception 'Admin access required';end if;if p_target_type='post' then update dm_private.community_posts set status=case p_action when'hide'then'hidden' when'restore'then'visible' when'lock'then'locked' when'unlock'then'visible' else status end,updated_at=now() where id=p_target_id;elsif p_target_type='comment' then update dm_private.community_comments set status=case when p_action='hide'then'hidden' when p_action='restore'then'visible' else status end where id=p_target_id;else raise exception 'Invalid target';end if;if not found then raise exception 'Community target not found';end if;insert into dm_private.community_moderation_log(actor_id,target_type,target_id,action,note)values(auth.uid(),p_target_type,p_target_id,p_action,nullif(trim(p_note),''));end $$;
revoke all on function public.community_feed(text,text),public.create_community_post(text,text,text,text),public.community_thread(uuid),public.add_community_comment(uuid,uuid,text),public.mark_community_helpful(uuid),public.report_community_content(uuid,uuid,text,text),public.admin_moderate_community(text,uuid,text,text) from public,anon;
grant execute on function public.community_feed(text,text),public.create_community_post(text,text,text,text),public.community_thread(uuid),public.add_community_comment(uuid,uuid,text),public.mark_community_helpful(uuid),public.report_community_content(uuid,uuid,text,text),public.admin_moderate_community(text,uuid,text,text) to authenticated;
